<!doctype html><html><head><meta charset="utf-8"><title>Invoice {{$order->reference}} · Al Asra</title><style>body{font:14px Arial;color:#222;margin:35px}.head{display:flex;justify-content:space-between;border-bottom:3px solid #F15A24;padding-bottom:18px}.brand{font-size:25px;font-weight:bold;color:#4A151B}.muted{color:#777}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}.total{font-size:19px;font-weight:bold;color:#4A151B}@media print{button{display:none}body{margin:15mm}}</style></head><body><div class="head"><div><div class="brand">AL ASRA</div><p class="muted">{{$store['name']}} · {{$store['email']}}</p></div><div><h1>INVOICE</h1><b>{{$order->reference}}</b><br>{{$order->created_at->format('d M Y')}}</div></div><h3>Bill to</h3><p>{{$order->customer_name}}<br>{{$order->customer_phone}}<br>{{$order->customer_email}}<br>{{$order->address_line}}, {{$order->city}} {{$order->province}}</p><table><thead><tr><th>Item</th><th>SKU</th><th>Qty</th><th>Unit price</th><th>Line total</th></tr></thead><tbody>@foreach($order->items as $item)<tr><td>{{$item->product_name}} @if($item->variant_name) — {{$item->variant_name}} @endif</td><td>{{$item->sku}}</td><td>{{$item->quantity}}</td><td>PKR {{number_format($item->unit_price,2)}}</td><td>PKR {{number_format($item->line_total,2)}}</td></tr>@endforeach</tbody></table><p class="right">Subtotal: PKR {{number_format($order->subtotal,2)}}<br>Discount: PKR {{number_format($order->discount_total,2)}}<br>Shipping: PKR {{number_format($order->shipping_fee,2)}}</p><p class="right total">Grand total: PKR {{number_format($order->grand_total,2)}}</p><p>Payment: {{$order->payment_method}} · {{str_replace('_',' ',$order->payment_status->value)}}</p><button onclick="window.print()">Print / Save PDF</button></body></html>
